<?php
namespace App\Models\Courses;
use App\Enums\Courses\CommercialDocumentType;use App\Enums\Courses\DeliveryStatus;use App\Models\Document;use Illuminate\Database\Eloquent\Relations\BelongsTo;
class CourseCommercialDocument extends CourseModel{protected $fillable=['course_enrollment_group_id','course_enrollment_id','document_id','type','series','number','issue_date','currency','subtotal_amount','igv_rate','igv_amount','total_amount','payer_name','payer_document_type','payer_document_number','observations','status','last_sent_at','delivery_status'];protected function casts():array{return ['type'=>CommercialDocumentType::class,'issue_date'=>'date','subtotal_amount'=>'decimal:2','igv_rate'=>'decimal:4','igv_amount'=>'decimal:2','total_amount'=>'decimal:2','last_sent_at'=>'datetime','delivery_status'=>DeliveryStatus::class];}public function group():BelongsTo{return $this->belongsTo(CourseEnrollmentGroup::class,'course_enrollment_group_id');}public function enrollment():BelongsTo{return $this->belongsTo(CourseEnrollment::class,'course_enrollment_id');}public function document():BelongsTo{return $this->belongsTo(Document::class);}}
